// Curated theme bundles: each bundles a kitty terminal theme with a complete GNOME/GTK palette.
// Colors are chosen to work together by human designers, not algorithmically generated.
//
// A bundle's `characteristics` object describes its overall feel so the wallpaper matcher can
// pick the closest one without inspecting every individual color.

/** @typedef {Object} ThemeBundle
 *  @property {string} name         Display name.
 *  @property {string} kitty        Kitty theme file name (without .conf).
 *  @property {Object} characteristics  Wallpaper-matching fingerprint.
 *  @property {number} characteristics.warmth    -1 (cool) … +1 (warm).
 *  @property {number} characteristics.saturation 0 (muted) … 1 (vivid).
 *  @property {number} characteristics.lightness  0 (dark) … 1 (light).
 *  @property {string} characteristics.chroma   "pastel" | "earth" | "cool" | "neon" | "warm" | "grey".
 *  @property {number} characteristics.accentHue   Hue of the accent in degrees (0-360).
 *  @property {Object} colors       GNOME / GTK semantic colors (hex strings).
 *  @property {string} gnomeAccent  Closest GNOME accent-color name.
 */

