/** All available curated bundles. */
export function getBundles() {
    return BUNDLES;
}

/** Find a bundle by its display name. */
export function getBundle(name) {
    return BUNDLES.find(b => b.name === name) ?? null;
}

/** Find a bundle by its kitty theme file name. */
export function getBundleByKitty(kitty) {
    return BUNDLES.find(b => b.kitty === kitty) ?? null;
}

/** Names of all bundles, for UI pickers. */
export function getBundleNames() {
    return BUNDLES.map(b => b.name);
}
